package com.theemeraldpig.hop;

import android.app.AlertDialog;
import android.content.Context;
import android.util.AttributeSet;
import android.util.Log;

import com.theemeraldpig.hop.mobile.EbitenView;

// The game view generated by ebitenmobile. If the game stops with an error, show it
// instead of leaving a black screen.
public class HopView extends EbitenView {
    private boolean shown;

    public HopView(Context context) { super(context); }
    public HopView(Context context, AttributeSet attrs) { super(context, attrs); }

    @Override
    protected void onErrorOnGameUpdate(Exception e) {
        Log.e("Hop", "game stopped", e);
        if (shown) return;
        shown = true;
        try {
            new AlertDialog.Builder(getContext())
                .setTitle("Orbit Hop ran into a problem")
                .setMessage(String.valueOf(e) + "\n\nPlease send a screenshot of this.")
                .setPositiveButton("OK", null)
                .show();
        } catch (Exception ignored) {
        }
    }
}
